const inputItem = $input.first();
const data = inputItem.json ?? {};
const body = data.body ?? data;
const binary = inputItem.binary ?? {};

function parseBoolean(value, fallback = true) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    return !['false', '0', 'no', 'nein'].includes(value.toLowerCase().trim());
  }
  return Boolean(value);
}

async function binaryCsvText() {
  const keys = ['file', 'data', 'csv'];
  for (const key of keys) {
    const file = binary[key];
    if (!file) continue;

    try {
      if (this?.helpers?.getBinaryDataBuffer) {
        const buffer = await this.helpers.getBinaryDataBuffer(0, key);
        return buffer.toString('utf8');
      }
    } catch (error) {}

    if (file.data && typeof file.data === 'string') {
      try {
        return Buffer.from(file.data, 'base64').toString('utf8');
      } catch (error) {}
    }
  }
  return undefined;
}

const uploadedCsvText = await binaryCsvText.call(this);
const csvText = uploadedCsvText || body.csv_text || body.csv || undefined;

return [{
  json: {
    csv_text: csvText,
    messages: body.messages || undefined,
    classifier: body.classifier || 'hybrid',
    matcher: body.matcher || 'embeddings',
    metadata_extractor: body.metadata_extractor || 'llm',
    write_output_files: parseBoolean(body.write_output_files, true),
    limit: body.limit
  }
}];

const response = $json;
const items = response.items ?? [];
const alerts = response.content_gap_alerts ?? [];

const actionCounts = {};
for (const item of items) {
  const action = item.final_action || item.decision?.final_action || 'unknown';
  actionCounts[action] = (actionCounts[action] || 0) + 1;
}

const reviewItems = items.filter(item => item.review_required || item.decision?.review_required);
const safetyItems = items.filter(item => (item.final_action || item.decision?.final_action) === 'route_to_safety_review');
const supportItems = items.filter(item => (item.final_action || item.decision?.final_action) === 'route_to_support');
const contentRequests = items.filter(item => (item.classification?.labels || []).includes('content_request'));

return [{
  json: {
    processed_count: response.processed_count ?? items.length,
    classifier: response.classifier,
    matcher: response.matcher,
    metadata_extractor: response.metadata_extractor,
    backend_exercise_records_loaded: response.exercise_records_loaded,
    outputs_written: response.outputs_written,
    output_dir: response.output_dir,
    action_counts: actionCounts,
    review_count: reviewItems.length,
    safety_count: safetyItems.length,
    support_count: supportItems.length,
    content_request_count: contentRequests.length,
    content_gap_alert_count: alerts.length,
    content_gap_alerts: alerts,
    review_items: reviewItems.map(item => ({
      message_id: item.message?.message_id,
      user_message: item.message?.user_message,
      labels: item.classification?.labels,
      final_action: item.final_action || item.decision?.final_action,
      match_status: item.match_status || item.decision?.match_status,
      priority: item.priority || item.decision?.priority,
      reason: item.decision_reason || item.decision?.reason
    })),
    processed_items: items
  }
}];

const reviews = $json.review_items ?? [];
const lines = reviews.map(item => `- ${item.message_id}: ${item.final_action} (${item.priority}) - ${item.user_message}`);

return [{
  json: {
    route: 'human_review_queue',
    review_count: reviews.length,
    channel: '#content-ops-review',
    title: reviews.length ? 'Human review required' : 'No human review required',
    text: reviews.length ? lines.join('\n') : 'No items require human review in this batch.',
    items: reviews
  }
}];

const alerts = $json.content_gap_alerts ?? [];
const tickets = alerts.map(alert => ({
  title: `Content gap: ${alert.theme}`,
  priority: alert.request_count >= 8 ? 'high' : 'medium',
  request_count: alert.request_count,
  message_ids: alert.message_ids,
  examples: alert.example_messages,
  recommended_action: alert.recommended_action,
  labels: ['content-gap', 'content-ops', 'ai-triage']
}));

return [{
  json: {
    route: 'content_gap_ticket',
    content_gap_alert_count: alerts.length,
    title: alerts.length ? 'Content gap alert' : 'No content gaps in this batch',
    tickets
  }
}];

const actionCounts = $json.action_counts ?? {};
const actionLines = Object.entries(actionCounts)
  .sort((a, b) => b[1] - a[1])
  .map(([action, count]) => `- ${action}: ${count}`)
  .join('\n');

return [{
  json: {
    route: 'daily_ops_digest',
    title: 'Reha ContentOps AI batch digest',
    text: [
      `Processed: ${$json.processed_count}`,
      `Exercise records loaded in backend: ${$json.backend_exercise_records_loaded}`,
      `Review items: ${$json.review_count}`,
      `Safety items: ${$json.safety_count}`,
      `Support items: ${$json.support_count}`,
      `Content gap alerts: ${$json.content_gap_alert_count}`,
      '',
      'Actions:',
      actionLines || '- none',
      '',
      `Outputs written: ${$json.outputs_written}`,
      $json.output_dir ? `Output dir: ${$json.output_dir}` : 'Output dir: not written'
    ].join('\n')
  }
}];

const summary = $json;
const items = summary.processed_items ?? summary.items ?? [];
const alerts = summary.content_gap_alerts ?? [];
const first = items[0] ?? {};
const decision = first.decision ?? {};
const classification = first.classification ?? {};
const labels = classification.labels ?? [];

const finalAction = first.final_action || decision.final_action || 'unknown';
const matchStatus = first.match_status || decision.match_status || 'unknown';

function normalizeStatus(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');
}

const normalizedMatchStatus = normalizeStatus(matchStatus);
const normalizedFinalAction = normalizeStatus(finalAction);

function labelIncludes(name) {
  return labels.includes(name);
}

function pickName(value) {
  if (!value) return null;

  if (typeof value === 'string') return value;

  if (typeof value === 'object') {
    return (
      value.name ||
      value.title ||
      value.exercise_name ||
      value.display_name ||
      value.slug ||
      value.id ||
      null
    );
  }

  return null;
}

function collectExerciseNames(item) {
  const found = [];

  function add(value) {
    if (!value) return;

    if (Array.isArray(value)) {
      for (const entry of value) add(entry);
      return;
    }

    const name = pickName(value);
    if (name && !found.includes(name)) found.push(name);

    if (typeof value === 'object') {
      add(value.exercise);
      add(value.exercise_record);
      add(value.content);
      add(value.item);
    }
  }

  add(item.matched_exercises);
  add(item.exercise_matches);
  add(item.matches);
  add(item.recommended_exercises);
  add(item.recommendations);
  add(item.match);
  add(item.best_match);
  add(item.matched_exercise);
  add(item.exercise);
  add(item.content);
  add(item.decision?.matched_exercises);
  add(item.decision?.exercise_matches);
  add(item.decision?.matches);
  add(item.decision?.best_match);
  add(item.decision?.matched_exercise);

  return found.slice(0, 3);
}

const exerciseNames = collectExerciseNames(first);

const isSafety =
  finalAction === 'route_to_safety_review' ||
  labelIncludes('safety') ||
  labelIncludes('medical_risk');

const isSupport =
  finalAction === 'route_to_support' ||
  labelIncludes('support') ||
  labelIncludes('bug_report') ||
  labelIncludes('technical_issue');

const isPositive =
  labelIncludes('positive_feedback') ||
  labelIncludes('praise') ||
  labelIncludes('positive');

const isContentRequest =
  labelIncludes('content_request') ||
  labelIncludes('exercise_request') ||
  finalAction === 'create_content_gap_ticket';

const isTrackOnly =
  normalizedMatchStatus === 'track_only' ||
  normalizedFinalAction === 'track_only';

const isNoMatch =
  [
    'no_match',
    'not_found',
    'none',
    'null',
    'unknown',
    'content_gap',
    'gap'
  ].includes(normalizedMatchStatus);

const isExistingContentMatch =
  [
    'existing_content',
    'existing_exercise',
    'existing_match',
    'matched_existing_content',
    'match_found',
    'matched',
    'exact_match',
    'semantic_match'
  ].includes(normalizedMatchStatus) ||
  normalizedFinalAction.includes('existing');

const hasExistingExercise =
  !isTrackOnly &&
  !isNoMatch &&
  isExistingContentMatch &&
  exerciseNames.length > 0;

let reply;
let replyType;
let showAsMatch = false;
let visibleMatchedExercises = [];

if (isSafety) {
  replyType = 'safety_review';
  reply = 'Danke für den Hinweis. Das klingt nach etwas, das wir sorgfältig prüfen sollten. Wir leiten dein Feedback an eine fachliche Review weiter.';
} else if (isSupport) {
  replyType = 'support';
  reply = 'Danke für den Hinweis. Das klingt nach einem technischen Problem. Wir geben das an den Support weiter.';
} else if (isPositive && !isContentRequest) {
  replyType = 'positive_feedback';
  reply = 'Danke für dein positives Feedback! Schön, dass dir die Übung beziehungsweise Erklärung geholfen hat.';
} else if (isTrackOnly) {
  replyType = 'content_gap';
  showAsMatch = false;
  visibleMatchedExercises = [];
  reply = 'Danke für deine Anfrage. Dazu haben wir aktuell noch keinen passenden bestehenden Inhalt gefunden. Wir merken uns das als Content-Wunsch.';
} else if (hasExistingExercise) {
  replyType = 'existing_exercise';
  showAsMatch = true;
  visibleMatchedExercises = exerciseNames;

  const list = exerciseNames.map(name => `„${name}“`).join(', ');
  reply = exerciseNames.length === 1
    ? `Ja, wir haben dazu bereits eine passende Übung: ${list}.`
    : `Ja, wir haben dazu bereits passende Übungen: ${list}.`;
} else if (isContentRequest || isNoMatch || !hasExistingExercise) {
  replyType = 'content_gap';
  showAsMatch = false;
  visibleMatchedExercises = [];
  reply = 'Danke für deine Anfrage. Dazu haben wir aktuell noch keinen passenden bestehenden Inhalt gefunden. Wir merken uns das als Content-Wunsch.';
} else {
  replyType = 'generic_feedback';
  showAsMatch = false;
  visibleMatchedExercises = [];
  reply = 'Danke für dein Feedback. Wir haben es aufgenommen und werten es für die Content-Planung aus.';
}

return [{
  json: {
    ok: true,
    reply,
    reply_type: replyType,
    show_as_match: showAsMatch,
    is_match: showAsMatch,
    matched_exercises: visibleMatchedExercises,
    detected_exercise_candidates: exerciseNames,
    final_action: finalAction,
    match_status: matchStatus,
    labels,
    processed_count: summary.processed_count ?? items.length,
    action_counts: summary.action_counts ?? {},
    review_count: summary.review_count ?? 0,
    safety_count: summary.safety_count ?? 0,
    support_count: summary.support_count ?? 0,
    content_request_count: summary.content_request_count ?? 0,
    content_gap_alert_count: summary.content_gap_alert_count ?? alerts.length,
    content_gap_alerts: alerts
  }
}];

