function parseJsonMaybe(value, fallback = {}) {
  if (value === undefined || value === null || value === '') return fallback;

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (error) {
      return { message: value };
    }
  }

  return value;
}

function parseBoolean(value, fallback = true) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    return !['false', '0', 'no', 'nein'].includes(value.toLowerCase().trim());
  }
  return Boolean(value);
}

const inputItem = $input.first();
const data = inputItem.json ?? {};
let body = data.body ?? data;

// Supports browser requests sent as text/plain to avoid CORS preflight.
body = parseJsonMaybe(body, body);

const userMessage =
  body.user_message ||
  body.message ||
  body.text ||
  body.feedback ||
  body.chat_message;

let messages = body.messages;

if (typeof messages === 'string') {
  try {
    messages = JSON.parse(messages);
  } catch (error) {
    messages = undefined;
  }
}

if (!messages && userMessage) {
  messages = [{
    message_id: body.message_id || `chat_${Date.now()}`,
    user_message: userMessage,
    source: body.source || 'chat_ui'
  }];
}

if (!Array.isArray(messages) || !messages.length) {
  throw new Error('No chat message found. Send { "message": "..." } or { "messages": [...] }.');
}

return [{
  json: {
    backend_url: body.backend_url || 'http://127.0.0.1:8000/process-feedback-batch',
    csv_text: undefined,
    messages,
    classifier: body.classifier || 'hybrid',
    matcher: body.matcher || 'embeddings',
    metadata_extractor: body.metadata_extractor || 'llm',
    write_output_files: parseBoolean(body.write_output_files, true),
    limit: body.limit,
    incoming_message: messages[0]?.user_message,
    incoming_message_id: messages[0]?.message_id
  }
}];

const response = $json;
const items = response.items ?? [];
const alerts = response.content_gap_alerts ?? [];

const actionCounts = {};
for (const item of items) {
