  actionCounts[action] = (actionCounts[action] || 0) + 1;
}

const reviewItems = items.filter(item => item.review_required || item.decision?.review_required);
const safetyItems = items.filter(item => (item.final_action || item.decision?.final_action) === 'route_to_safety_review');
const supportItems = items.filter(item => (item.final_action || item.decision?.final_action) === 'route_to_support');
const contentRequests = items.filter(item => (item.classification?.labels || []).includes('content_request'));

return [{
  json: {
    processed_count: response.processed_count ?? items.length,
    classifier: response.classifier,
    matcher: response.matcher,
    metadata_extractor: response.metadata_extractor,
    backend_exercise_records_loaded: response.exercise_records_loaded,
    outputs_written: response.outputs_written,
    output_dir: response.output_dir,
    action_counts: actionCounts,
    review_count: reviewItems.length,
    safety_count: safetyItems.length,
    support_count: supportItems.length,
    content_request_count: contentRequests.length,
    content_gap_alert_count: alerts.length,
    content_gap_alerts: alerts,
    review_items: reviewItems.map(item => ({
      message_id: item.message?.message_id,
      user_message: item.message?.user_message,
      labels: item.classification?.labels,
      final_action: item.final_action || item.decision?.final_action,
      match_status: item.match_status || item.decision?.match_status,
      priority: item.priority || item.decision?.priority,
      reason: item.decision_reason || item.decision?.reason
    })),
    processed_items: items
  }
}];

